            longs.values = ArrayUtil.grow(longs.values, count);
        }
        int middle = firstValue + count / 2;
        long median;
        if (count % 2 == 1) {
            median = values.getLong(middle);
        } else {
            BigInteger a = unsignedLongToBigInteger(values.getLong(middle - 1));
            BigInteger b = unsignedLongToBigInteger(values.getLong(middle));
            median = bigIntegerToUnsignedLong(a.add(b).shiftRight(1));
        }
        for (int i = 0; i < count; i++) {
            long value = values.getLong(firstValue + i);
            longs.values[i] = value > median ? unsignedLongSubtractExact(value, median) : unsignedLongSubtractExact(median, value);
        }
        return unsignedLongMedianOf(longs.values, count);
    }

    static long singleUnsignedLong(long value) {
        return NumericUtils.ZERO_AS_UNSIGNED_LONG;
    }

    static long unsignedLongMedianOf(long[] values, int count) {
        // TODO quickselect
        Arrays.sort(values, 0, count);
        int middle = count / 2;
        if (count % 2 == 1) {
            return values[middle];
        }
        BigInteger a = unsignedLongToBigInteger(values[middle - 1]);
        BigInteger b = unsignedLongToBigInteger(values[middle]);
        return bigIntegerToUnsignedLong(a.add(b).shiftRight(1));
    }

    static class Ints {
        public int[] values = new int[2];
        public int count;
    }

    @MvEvaluator(extraName = "Int", finish = "finish", ascending = "ascending", single = "single")
    static void process(Ints ints, int v) {
        if (ints.values.length < ints.count + 1) {
            ints.values = ArrayUtil.grow(ints.values, ints.count + 1);
        }
        ints.values[ints.count++] = v;
    }

    static int finish(Ints ints) {
        int median = intMedianOf(ints.values, ints.count);
        for (int i = 0; i < ints.count; i++) {
            int value = ints.values[i];
            ints.values[i] = value > median ? Math.subtractExact(value, median) : Math.subtractExact(median, value);
        }
        int mad = intMedianOf(ints.values, ints.count);
        ints.count = 0;
        return mad;
    }

    /**
     * If the values are ascending pick the middle value or average the two middle values together.
     */
    static int ascending(Ints ints, IntBlock values, int firstValue, int count) {
        if (ints.values.length < count) {
            ints.values = ArrayUtil.grow(ints.values, count);
        }
        int middle = firstValue + count / 2;
        int median = count % 2 == 1 ? values.getInt(middle) : avgWithoutOverflow(values.getInt(middle - 1), values.getInt(middle));
        for (int i = 0; i < count; i++) {
            int value = values.getInt(firstValue + i);
            ints.values[i] = value > median ? Math.subtractExact(value, median) : Math.subtractExact(median, value);
        }
        return intMedianOf(ints.values, count);
    }

    static int single(int value) {
        return 0;
    }

    static int intMedianOf(int[] values, int count) {
        // TODO quickselect
        Arrays.sort(values, 0, count);
        int middle = count / 2;
        return count % 2 == 1 ? values[middle] : avgWithoutOverflow(values[middle - 1], values[middle]);
    }

    /**
     * Average two {@code int}s together without overflow.
     */
    static int avgWithoutOverflow(int a, int b) {
        return (a & b) + ((a ^ b) >> 1);
    }
}

public class MvMedianAbsoluteDeviationTests extends AbstractMultivalueFunctionTestCase {
    public MvMedianAbsoluteDeviationTests(@Name("TestCase") Supplier<TestCaseSupplier.TestCase> testCaseSupplier) {
        this.testCase = testCaseSupplier.get();
    }

    @ParametersFactory
    public static Iterable<Object[]> parameters() {
        List<TestCaseSupplier> cases = new ArrayList<>();
        doubles(cases, "mv_median_absolute_deviation", "MvMedianAbsoluteDeviation", (size, valuesStream) -> {
            var values = valuesStream.sorted().toArray();
            int middle = size / 2;
            if (size % 2 == 1) {
                double median = values[middle];
                return equalTo(Arrays.stream(values).map(d -> Math.abs(d - median)).sorted().skip(middle).findFirst().orElseThrow());
            } else {
                double median = (values[middle - 1] + values[middle]) / 2;
                return equalTo(
                    Arrays.stream(values).map(d -> Math.abs(d - median)).sorted().skip(middle - 1).limit(2).average().orElseThrow()
                );
            }
        });
        ints(cases, "mv_median_absolute_deviation", "MvMedianAbsoluteDeviation", (size, values) -> {
            var mad = calculateMedianAbsoluteDeviation(size, values.mapToObj(BigInteger::valueOf));
            return equalTo(mad.intValue());
        });
        longs(cases, "mv_median_absolute_deviation", "MvMedianAbsoluteDeviation", (size, values) -> {
            var mad = calculateMedianAbsoluteDeviation(size, values.mapToObj(BigInteger::valueOf));
            return equalTo(mad.longValue());
        });
        unsignedLongs(cases, "mv_median_absolute_deviation", "MvMedianAbsoluteDeviation", (size, values) -> {
            var mad = calculateMedianAbsoluteDeviation(size, values);
            return equalTo(mad);
        });

        cases.addAll(
            List.of(
                // Simple cases
                new TestCaseSupplier(
                    "mv_median_absolute_deviation(<1, 2>)",
                    List.of(DataType.INTEGER),
                    () -> new TestCaseSupplier.TestCase(
                        List.of(new TestCaseSupplier.TypedData(List.of(1, 2), DataType.INTEGER, "field")),
                        "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                        DataType.INTEGER,
                        equalTo(0)
                    )
                ),
                new TestCaseSupplier(
                    "mv_median_absolute_deviation(<-1, -2>)",
                    List.of(DataType.INTEGER),
                    () -> new TestCaseSupplier.TestCase(
                        List.of(new TestCaseSupplier.TypedData(List.of(-1, -2), DataType.INTEGER, "field")),
                        "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                        DataType.INTEGER,
                        equalTo(0)
                    )
                ),

                // Custom double overflow, as "MAX_DOUBLE + 1000 == MAX_DOUBLE"
                new TestCaseSupplier(
                    "mv_median_absolute_deviation(<min_double, big_number, same_big_number>)",
                    List.of(DataType.DOUBLE),
                    () -> new TestCaseSupplier.TestCase(
                        List.of(
                            new TestCaseSupplier.TypedData(
                                List.of(-Double.MAX_VALUE, Double.MAX_VALUE / 4, Double.MAX_VALUE / 4),
                                DataType.DOUBLE,
                                "field"
                            )
                        ),
                        "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                        DataType.DOUBLE,
                        equalTo(0.)
                    )
                )
            )
        );

        cases.addAll(
            overflowCasesFor(
                DataType.INTEGER,
                Integer.MAX_VALUE,
                Integer.MIN_VALUE,
                Integer.MAX_VALUE,
                Integer.MAX_VALUE / 2,
                Integer.MAX_VALUE / 2 + 1
            )
        );
        cases.addAll(
            overflowCasesFor(DataType.LONG, Long.MAX_VALUE, Long.MIN_VALUE, Long.MAX_VALUE, Long.MAX_VALUE / 2L, Long.MAX_VALUE / 2L + 1)
        );
        cases.addAll(
            overflowCasesFor(
                DataType.DOUBLE,
                Double.MAX_VALUE,
                -Double.MAX_VALUE,
                Double.MAX_VALUE,
                Double.MAX_VALUE / 2.,
                Double.MAX_VALUE / 2.
            )
        );
        cases.addAll(
            overflowCasesFor(
                DataType.UNSIGNED_LONG,
                NumericUtils.asLongUnsigned(NumericUtils.UNSIGNED_LONG_MAX),
                NumericUtils.ZERO_AS_UNSIGNED_LONG,
                NumericUtils.UNSIGNED_LONG_MAX.divide(BigInteger.valueOf(2)),
                NumericUtils.UNSIGNED_LONG_MAX.divide(BigInteger.valueOf(2)),
                BigInteger.ZERO
            )
        );

        return parameterSuppliersFromTypedDataWithDefaultChecks(false, cases, (v, p) -> "numeric");
    }

    private static List<TestCaseSupplier> overflowCasesFor(
        DataType type,
        Number max,
        Number min,
        Number maxMinMad,
        Number maxZeroMad,
        Number minZeroMad
    ) {
        var zeroExpected = DataTypeConverter.convert(0, type);
        var zeroValue = type == DataType.UNSIGNED_LONG ? NumericUtils.ZERO_AS_UNSIGNED_LONG : zeroExpected;
        var oneThousandValue = type == DataType.UNSIGNED_LONG
            ? NumericUtils.asLongUnsigned(BigInteger.valueOf(1000))
            : DataTypeConverter.convert(1000, type);

        var typeName = type.name().toLowerCase();

        return List.of(
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<max_" + typeName + ", min_" + typeName + ">)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(max, min), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(maxMinMad)
                )
            ),
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<max_" + typeName + ", 0>)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(max, zeroValue), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(maxZeroMad)
                )
            ),
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<min_" + typeName + ", 0>)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(min, zeroValue), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(minZeroMad)
                )
            ),
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<max_" + typeName + ", max_" + typeName + ">)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(max, max), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(zeroExpected)
                )
            ),
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<min_" + typeName + ", min_" + typeName + ">)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(min, min), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(zeroExpected)
                )
            ),
            new TestCaseSupplier(
                "mv_median_absolute_deviation(<min_" + typeName + ", 1000, 1000>)",
                List.of(type),
                () -> new TestCaseSupplier.TestCase(
                    List.of(new TestCaseSupplier.TypedData(List.of(min, oneThousandValue, oneThousandValue), type, "field")),
                    "MvMedianAbsoluteDeviation[field=Attribute[channel=0]]",
                    type,
                    equalTo(zeroExpected)
                )
            )
        );
    }

    private static BigInteger calculateMedianAbsoluteDeviation(int size, Stream<BigInteger> valuesStream) {
        var values = valuesStream.sorted().toArray(BigInteger[]::new);
        int middle = size / 2;
        if (size % 2 == 1) {
            var median = values[middle];
            return Arrays.stream(values).map(bi -> bi.subtract(median).abs()).sorted().skip(middle).findFirst().orElseThrow();
        } else {
            var median = values[middle - 1].add(values[middle]).divide(BigInteger.valueOf(2));
            return Arrays.stream(values)
                .map(bi -> bi.subtract(median).abs())
                .sorted()
                .skip(middle - 1)
                .limit(2)
                .reduce(BigInteger.ZERO, BigInteger::add)
                .divide(BigInteger.valueOf(2));
        }
    }

    @Override
    protected Expression build(Source source, Expression field) {
        return new MvMedianAbsoluteDeviation(source, field);
    }
